import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"AI4Paper 使用指南","description":"","frontmatter":{"plugin":"wdcpclover/ai4paper","title":"AI4Paper 使用指南"},"headers":[],"relativePath":"user-guide/plugins/ai4paper.md","filePath":"wiki/user-guide/plugins/ai4paper.md"}`),u=Object.assign({name:`user-guide/plugins/ai4paper.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginsai4paper.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`ai4paper`,tabindex:`-1`},[o(`AI4Paper `),i(`a`,{class:`header-anchor`,href:`#ai4paper`,"aria-label":`Permalink to “AI4Paper”`},`​`)],-1),r(s),u[2]||=a(`<p>AI4Paper 是一款面向文献阅读与整理的 Zotero 插件，把 PDF 全文翻译、文库问答、文献检索和期刊分区显示等功能集成在 Zotero 内部，不需要在多个软件之间来回切换。</p><div class="warning custom-block"><p class="custom-block-title">关于收费</p><p>AI4Paper 是一款商业插件，采用「基础功能免费 + AI 功能按量计费」的模式：</p><ul><li>期刊分区与影响因子显示、PDF 识别与整理等基础功能长期免费；</li><li>全文翻译、文库问答、文献综述等需要调用大模型的功能会消耗额度，注册账号后赠送一定额度和为期 7 天的全功能试用，之后需要订阅套餐；</li><li>也可以在插件设置中填入你自己的模型服务信息，此时不消耗插件方的额度。</li></ul></div><nav class="table-of-contents"><ul><li><a href="#主要功能">主要功能</a><ul><li><a href="#pdf-全文翻译">PDF 全文翻译</a></li><li><a href="#与文献对话">与文献对话</a></li><li><a href="#文库知识库">文库知识库</a></li><li><a href="#文献检索与入库">文献检索与入库</a></li><li><a href="#期刊分区与影响因子">期刊分区与影响因子</a></li></ul></li><li><a href="#安装">安装</a></li><li><a href="#登录账号">登录账号</a></li><li><a href="#使用自己的模型服务">使用自己的模型服务</a></li><li><a href="#常见问题">常见问题</a><ul><li><a href="#安装后看不到插件界面">安装后看不到插件界面</a></li><li><a href="#ai-功能提示未登录">AI 功能提示未登录</a></li><li><a href="#全文翻译后找不到译文">全文翻译后找不到译文</a></li></ul></li></ul></nav><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to “主要功能”">​</a></h2><h3 id="pdf-全文翻译" tabindex="-1">PDF 全文翻译 <a class="header-anchor" href="#pdf-全文翻译" aria-label="Permalink to “PDF 全文翻译”">​</a></h3><p>对文库中的 PDF 一键发起全文翻译，输出保留原排版的双语对照文件，并作为附件回存到原条目下，便于后续检索和引用。也支持在阅读器中划词翻译，以及在阅读界面侧边栏中查看译文。</p><h3 id="与文献对话" tabindex="-1">与文献对话 <a class="header-anchor" href="#与文献对话" aria-label="Permalink to “与文献对话”">​</a></h3><p>在阅读器中就当前 PDF 提问，或让插件生成整篇论文的摘要与精读笔记，结果可以保存为 Zotero 笔记。</p><h3 id="文库知识库" tabindex="-1">文库知识库 <a class="header-anchor" href="#文库知识库" aria-label="Permalink to “文库知识库”">​</a></h3><p>将文库中的文献建立为可检索的知识库，跨多篇文献提问并给出出处，也可以据此整理综述提纲。</p><h3 id="文献检索与入库" tabindex="-1">文献检索与入库 <a class="header-anchor" href="#文献检索与入库" aria-label="Permalink to “文献检索与入库”">​</a></h3><p>在插件内检索外部文献数据源，检索结果可以直接保存到指定分类中，配合 Zotero Connector 使用可以覆盖大部分找文献的场景。</p><h3 id="期刊分区与影响因子" tabindex="-1">期刊分区与影响因子 <a class="header-anchor" href="#期刊分区与影响因子" aria-label="Permalink to “期刊分区与影响因子”">​</a></h3><p>在条目列表中新增期刊分区、影响因子等列，可以按列排序和筛选，用于快速判断文献质量。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">版本要求</p><p>AI4Paper 支持 Zotero 7 及以上版本，不支持 Zotero 6 及更早版本。</p></div><p>下载 <code>.xpi</code> 文件后，在 Zotero 中依次点击「工具」-&gt;「插件」，点击右上角的齿轮图标选择「Install Plugin From File...」，选中该文件并确认，然后重启 Zotero。</p><p>获取插件与安装的通用说明参见 <a href="./about-plugin">关于 Zotero 插件</a>。</p><h2 id="登录账号" tabindex="-1">登录账号 <a class="header-anchor" href="#登录账号" aria-label="Permalink to “登录账号”">​</a></h2><p>插件的 AI 功能需要登录后使用：</p><ol><li>在官网注册账号，注册时请设置邮箱和密码；</li><li>在 Zotero 中依次点击「编辑」-&gt;「首选项」（macOS 为「Zotero」-&gt;「设置」）；</li><li>在左侧列表中选择「AI4Paper」，然后打开「账户与会员」；</li><li>使用注册时的邮箱和密码登录。</li></ol><div class="warning custom-block"><p class="custom-block-title">使用微信注册的用户</p><p>插件端只支持邮箱与密码登录。如果你在官网使用微信扫码注册，请先在官网的账号页面补充绑定邮箱并设置密码，否则无法在插件中登录。</p></div><h2 id="使用自己的模型服务" tabindex="-1">使用自己的模型服务 <a class="header-anchor" href="#使用自己的模型服务" aria-label="Permalink to “使用自己的模型服务”">​</a></h2><p>如果你已经有可用的模型服务，可以在插件设置的「配置 AI 服务」中填写服务地址、密钥和模型名称。填写后插件会优先使用你自己的服务，不再消耗插件方的额度。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="安装后看不到插件界面" tabindex="-1">安装后看不到插件界面 <a class="header-anchor" href="#安装后看不到插件界面" aria-label="Permalink to “安装后看不到插件界面”">​</a></h3><p>请确认已经完全退出并重新启动 Zotero。插件需要重启后才会加载。</p><h3 id="ai-功能提示未登录" tabindex="-1">AI 功能提示未登录 <a class="header-anchor" href="#ai-功能提示未登录" aria-label="Permalink to “AI 功能提示未登录”">​</a></h3><p>请在「首选项」-&gt;「AI4Paper」-&gt;「账户与会员」中确认登录状态，以及所用账号是否处于试用期或订阅有效期内。</p><h3 id="全文翻译后找不到译文" tabindex="-1">全文翻译后找不到译文 <a class="header-anchor" href="#全文翻译后找不到译文" aria-label="Permalink to “全文翻译后找不到译文”">​</a></h3><p>译文会作为附件保存在原条目下，展开条目即可看到；如果条目下附件较多，可以按添加时间排序查找。</p>`,31),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};